        content: "심혈관계 질환이 있다면 모리모리액5 사용 전 의사 상담이 필수예요. 임부 또는 임신 가능성이 있는 여성, 수유부도 사용 금지예요. 심혈관계 질환(관상동맥 질환, 부정맥, 심부전, 고혈압·저혈압) 환자도 미녹시딜을 사용하면 안 돼요.\n\n외용 코르티코이드, 레티노이드, 바셀린, 구아네티딘 같은 혈관확장제와 함께 사용하지 마세요. 경피 흡수가 과도하게 증가해서 전신 부작용 위험이 높아져요. 두피에 홍반, 염증, 감염, 건선, 일광화상이 있는 경우에도 사용을 피해야 해요.\n\n모리모리액5은 외용 전용이에요. 두피 이외의 부위에는 절대 도포하지 않아요. 4개월 이상 사용해도 증상 개선이 없다면 사용을 중단하고 의사와 상의하세요. 갑작스러운 탈모나 원형탈모라면 미녹시딜이 아닌 다른 치료가 필요해요.",
