        "content": "다모녹실액5%(미녹시딜)는 (주)티디에스팜이 만든 5% 미녹시딜 외용 액제예요. 식약처 품목번호는 202001675이고, 모발용제(발모·탈모·염모·양모제)로 분류된 일반의약품이죠. 허가받은 적응증은 남성형 탈모증(안드로젠탈모증)의 치료예요. 5% 농도는 여기까지가 허가 범위고, 여성형 탈모는 2%·3% 농도가 맡아요.\n\n바르는 약이라는 점이 중요해요. 두피에 직접 도포해 환부에 작용하는 외용 액제죠. 그래서 먹는 탈모약과 달리 도포법과 두피 상태가 효과와 부작용을 함께 좌우해요. 식약처 허가사항은 최소 4개월 동안 꾸준히 발라야 효과를 가늠할 수 있다고 안내하고, 사용을 멈추면 탈모가 다시 진행될 수 있다고도 적어요. 부작용이 걱정돼 농도나 제품을 바꿀 때는 효과 판단 기간까지 함께 의사·약사와 상의하는 게 좋아요."
