    "metaDescription": "휴메리나정0.5밀리그램(두타스테리드)은 휴온스의 전문의약품으로 식약처 품목번호 202004007로 허가되었다. 30정 기준가 6,000원, 1정당 200원, 두타스테리드 0.5mg 동일성분 45개 제품 중 최저가 그룹이다. 처방전 발급부터 약국 구입 경로, 한 달 복용 비용까지 허가사항 원문으로 정리한다.",
