      {
        "title": "휴메리나정은 처방전 받아 어떻게 약국에서 사나요?",
        "content": "휴메리나정은 처방전이 있어야 약국에서 살 수 있는 전문의약품이에요(식약처 품목번호 202004007). 약국에서 바로 집어 계산하는 일반의약품과 달라요. 먼저 병원이나 의원에서 진료를 받고 처방전을 발급받아야 해요. 그 처방전을 약국에 내면 휴메리나정을 조제받는 구조죠.\n\n비용은 두 군데서 나뉘어 나가요. 하나는 병·의원 진료비와 처방전 발급 비용이에요. 다른 하나는 약국에서 내는 약값 6,000원이죠. 그래서 약값만 검색해 6,000원이라고 생각하고 갔다가, 진료비를 더하면 첫 달 체감 비용이 더 크게 느껴질 수 있어요.\n\n약값을 아끼는 현실적인 방법은 단가 흥정이 아니에요. 방문 설계예요. 두타스테리드는 장기 복용하는 약이라, 진료 때 여러 달치를 한꺼번에 처방받으면 진료 횟수와 약국 방문이 줄어요. 약 단가는 1정당 200원으로 고정이라, 줄일 수 있는 건 반복 진료에 드는 부대 비용이거든요. 처방받은 약국에서 조제 가격을 확인하고, 같은 성분 기준가는 아래 버튼에서 비교해 보세요."
      },
      {
        "title": "휴메리나정 복용법은 어떻게 되나요?",
        "content": "휴메리나정의 권장 용량은 1일 1회 1정(0.5mg)이에요. 식약처 허가사항 기준 식사와 관계없이 복용할 수 있어요. 그래서 본인이 기억하기 쉬운 시간에 맞추면 돼요. 정제를 씹거나 쪼개지 말고 통째로 삼켜 복용하는 게 원칙이죠.\n\n쪼개면 안 되는 이유가 안전 문제와 연결돼요. 두타스테리드는 피부로 흡수되는 성분이거든요. 부서진 조각을 임신했거나 임신 가능성이 있는 여성이 만지면 남자 태아에게 위험할 수 있어요. 그래서 1일 1정을 그대로 삼키는 단순한 복용법이 곧 안전 수칙이기도 해요.\n\n신장애 환자나 노인은 용량을 따로 조절할 필요가 없어요. 다만 간장애 환자는 투여 자료가 없어서 권장 용량이 확립돼 있지 않죠. 1정당 200원짜리 약이라 비용 부담은 작아요. 용량을 임의로 늘린다고 효과가 더 빨라지지 않으니 1일 1정을 지키는 게 중요해요. 복용 변경은 의사와 상의하세요."
      },
      {
        "title": "휴메리나정 부작용은 어떤 게 있나요?",
        "content": "식약처 허가사항 기준 휴메리나정의 부작용은 대부분 경증에서 중등증이에요. 주로 생식기계와 관련 있죠. 남성형 탈모 위약대조 3상 임상시험에서 두타스테리드 0.5mg 투여군(n=184)은 6개월 동안 발기기능장애 5%, 성욕감소 2%가 보고됐어요. 위약군은 각각 3%, 1%였어요.\n\n국내 시판 후 조사 자료도 있어요. 남성형 탈모 치료를 위해 휴메리나정 성분을 투여받은 성인 남성(18~41세) 712명 가운데, 약물과 인과관계를 배제할 수 없는 약물유해반응 발현율은 9.3%(66명)였어요. 성욕감소, 소화불량, 발기부전, 피로 순으로 보고됐죠.\n\n주의할 점은 반감기예요. 두타스테리드는 반감기가 약 3~5주로 길어요. 복용을 멈춰도 성분이 한동안 몸에 남거든요. 그래서 임신부에게 약이 전달되는 걸 막기 위해, 마지막 복용 후 최소 6개월이 지날 때까지 헌혈하면 안 돼요. 이런 신호가 불편하면 임의 중단보다 의사와 먼저 상의하세요."
      },
      {
        "title": "휴메리나정은 누가 쓰면 안 되나요?",
        "content": "식약처 허가사항상 휴메리나정은 여성과 18세 미만 소아에게 금기예요. 두타스테리드가 피부를 통해 흡수되기 때문이죠. 임신했거나 임신 가능성이 있는 여성은 이 약을 취급해서도 안 되고, 부서지거나 깨진 정제 조각을 만져서도 안 돼요. 남자 태아의 외부 생식기 발달에 영향을 줄 수 있어서예요.\n\n이 약이나 다른 5알파환원효소 억제제에 과민증이 있는 환자도 복용하면 안 돼요. 임신을 계획하는 성인 남성은 생식능에 영향을 줄 수 있어서 의사 판단 하에 신중히 투여해야 해요. 요잔류량이 크거나 중증 요류 감소가 있는 환자, 간장애 환자도 신중 투여 대상이죠.\n\n전립선암 검진도 알아둘 부분이에요. 허가사항에 따르면 이 약은 PSA 수치를 낮춰요. 그래서 복용 중이라면 검사 전에 휴메리나정 복용 사실을 의사에게 알려야 정확히 해석돼요. 전문의약품이라 처방 단계에서 이런 금기와 주의사항을 의사가 확인하니, 진료 비용은 약값 6,000원에 더해지는 안전 비용이라고 볼 수 있어요."
      }
