        content: "여성과 소아는 유힐릭스정을 절대 복용하면 안 돼요. 임부 또는 임신 가능성 있는 여성은 캡슐 내용물에 피부가 닿는 것만으로도 남성 태아 생식기 발달에 이상을 일으킬 수 있어요.\n\nPSA 수치가 약 40~50% 감소하므로 전립선암 검진 시 6개월 복용 후 새 PSA 기저치를 설정하는 게 권장돼요. 다른 5α-환원효소 억제제(피나스테리드)와 병용하지 마세요. CYP3A4 억제제(리토나비르, 케토코나졸 등)를 복용 중이면 두타스테리드 혈중 농도가 상승할 수 있어요.\n\n헌혈은 복용 중단 후 6개월 후에 가능해요. 피나스테리드의 1개월보다 훨씬 길어요. 반감기가 긴 만큼 체내에서 약이 완전히 빠지는 데 오래 걸리기 때문이에요. 간 기능에 문제가 있는 환자는 복용 전 의사와 상담해야 해요.",
