        content: "우리들두타스테리드연질캡슐은 양성 전립선비대증(BPH) 치료와 성인 남성의 남성형 탈모증(안드로젠탈모증) 치료에 허가받았어요. 전립선비대증에서는 전립선 크기를 줄여 배뇨 증상을 개선하고, 급성 요폐 발생 위험과 수술 필요성을 낮춰요.\n\n탈모 치료 효과를 판단하려면 최소 6개월 이상 복용해야 해요. 피나스테리드로 효과가 부족하거나 탈모가 빠르게 진행되는 경우에 두타스테리드로 전환하는 경우가 있어요. 복용을 중단하면 탈모가 다시 진행되는데, 반감기가 길어서 중단 후에도 당분간 효과가 유지되다가 서서히 사라져요.\n\n원형탈모, 여성형 탈모, 출산 관련 탈모에는 허가가 없고 효과도 없어요. 피부과나 비뇨기과에서 진단 후 처방받아야 하는 전문의약품이에요.",
