        "title": "아보텍트정 정확한 복용법은 어떤 단계인가요?",
        "content": "식약처 허가사항의 권장용량은 1일 1회 1정(0.5mg)이에요. 핵심은 삼키는 방식이에요. 통째로 삼켜요. 이 약은 씹거나 쪼개지 않고 통째로 삼켜 복용해야 해요. 한 알을 충분한 물과 함께 한 번에 넘기는 게 1단계예요. 입에서 굴리며 녹이거나 반으로 잘라 먹는 건 허가된 방식이 아니에요. 2단계는 시간 정하기인데, 이 약은 식사와 관계없이 복용할 수 있어서 끼니에 맞출 필요가 없어요. 시간은 자유예요. 아침이든 저녁이든 본인이 매일 지키기 쉬운 시간을 하나 골라 1일 1회 1정만 지키면 돼요. 3단계는 용량 조절 여부 확인이에요. 신장애 환자나 노인 환자에서 이 약의 용량을 조절할 필요는 없다고 허가사항에 적혀 있어요. 다만 간장애 환자에게 투여한 자료가 없어서, 간장애 환자에서의 권장용량은 확립돼 있지 않아요. 정리하면 물과 함께 통째로, 1일 1회 1정, 식사 무관, 이 세 가지가 복용법의 뼈대예요. 약을 바꾸거나 멈출지는 혼자 정하지 말고 의사와 상의하는 게 좋아요."
