        "content": "통째로 삼키라는 규칙은 단순한 권장이 아니라 안전 문제예요. 식약처 허가사항을 보면 이 약은 피부를 통해서 흡수돼요. 그래서 누가 만지느냐가 중요해요. 허가사항은 임신했거나 임신 가능성이 있는 여성이 이 약을 취급해서는 안 되고, 부서지거나 깨진 조각을 만져서도 안 된다고 경고해요. 흡수된 두타스테리드 0.5mg 성분이 남자 태아의 발달에 미치는 위험 때문이죠. 소아도 마찬가지로, 피부를 통해 흡수되므로 부서지거나 깨진 조각을 만져서는 안 된다고 적혀 있어요. 그러니 약을 쪼개 절반만 먹거나 가루로 부숴 먹는 건 본인 용량 문제를 넘어, 같이 사는 가족에게 위험을 옮기는 행동이에요. 코팅이 멀쩡한 한 정 그대로일 때는 표면이 보호막 역할을 해서 이런 위험이 차단돼요. 그래서 임의로 자르면 안 돼요. 이유가 여기 있어요. 보관할 때도 원래 용기에 그대로 두는 게 품질과 안전 양쪽에 좋아요."
