        "content": "통째로 삼키라는 지시는 기호의 문제가 아니라 제형에서 나온 안전 조건이에요. 그 근거가 식약처 허가사항에 분명히 적혀 있죠. 캡슐 내용물에 노출되면 구강·인두 점막에 자극이 생길 수 있으니 씹거나 쪼개지 말고 통째로 삼키라는 내용이에요. 젤 막 안쪽이 액상 약물로 채워져 있다 보니, 깨무는 순간 그 액체가 입안 점막에 직접 묻어요. 단단한 정제를 쪼개는 것과는 위험의 성격이 달라요. 또 하나는 누출이에요. 이 약은 피부로도 흡수되기에, 허가사항은 임신했거나 임신 가능성이 있는 여성에게 새는 캡슐과 닿지 말라고 일러요. 캡슐이 새어 약에 접촉했다면 그 자리를 곧바로 물과 비누로 씻으라고도 안내하죠. 흡수된 두타스테리드 0.5mg이 남자 태아의 외부 생식기 형성을 방해할 수 있다는 게 이유예요. 같은 맥락에서 소아 역시 누출된 캡슐을 만지면 안 돼요. 그러니 캡슐을 터뜨려 짜 먹는 행위는 내 복용량을 넘어 곁의 가족까지 위태롭게 만드는 일이에요. 반대로 막이 온전하면 약물이 새지 않아, 그대로 삼키는 게 제일 안전하죠."
