    "metaDescription": "두타칸연질캡슐을 복용할 때 간장애·심부전 같은 동반질환에서 달라지는 부작용 해석과 즉시 멈출 신호, 연질캡슐 누출 주의, 식약처 허가사항 기준 안전 요령, 동일성분 45종 중 가격 위치를 정리한 글입니다.",
