        "question": "심장약이나 다른 약을 같이 먹는데 두타칸연질캡슐, 처음에 뭘 챙겨야 하나요?",
        "answer": "지금 먹는 약을 진료실에서 통째로 보여 주는 게 출발이에요. 두타스테리드는 간 효소 CYP3A4가 분해하는데, 그 효소를 강하게 누르는 리토나비르 같은 약과 오래 겹치면 농도가 솟을 수 있다고 식약처 허가사항이 알려 줘요. 심장 질환자라면 알파차단제와 함께 쓴 4년 임상에서 심부전 보고가 잦았다는 기록도 함께 짚는 편이 좋죠. 6,000원 약값을 비교하는 건 이 점검 다음이에요."
