        "answer": "끊었는데 증상이 그대로라면 긴 반감기를 먼저 떠올려 보세요. 발기부전, 성욕감소, 사정장애 같은 성기능 반응은 복용을 멈춘 뒤에도 한동안 남을 수 있다고 허가사항에 적혀 있어요. 그래서 잔여 증상의 원인이 정말 이 약인지부터 진료로 가려야 하죠. 재개도 전문의약품이라 처방을 거쳐야 하고, 다른 5알파환원효소 억제제와 동시 복용은 막혀 있어요."
