        "content": "두타베린정은 식약처 허가사항상 양성 전립선 비대증 증상 개선과 성인 남성(만 18~50세)의 남성형 탈모 치료에 쓰여요. 양성 전립선 비대증에서는 급성 요저류 위험성을 줄이고 관련 수술 필요성을 낮추는 효과가 허가돼 있죠.\n\n두타스테리드는 사람의 CYP3A4로 대사되고 반감기가 약 3~5주로 길어요. 이 긴 반감기는 혈중 농도를 안정적으로 잡아 주지만, 지병이 있는 분에게는 양날의 칼이에요. 부작용이 찾아와도 그만큼 오래 머물 수 있으니까요. 효과든 부작용이든 한 박자 늦게 오고 늦게 빠진다고 이해하면 돼요. 효과 판단이나 약 변경은 의사와 상의하는 게 맞아요."
