        "content": "먼저 금기부터 확인해요. 식약처 허가사항은 여성, 18세 미만의 소아, 이 약이나 다른 5α-환원효소 억제제에 과민증이 있는 환자에게 투여하지 말라고 명시해요. 유당을 함유하고 있어서 갈락토오스 불내성이나 유당분해효소 결핍 같은 유전적 문제가 있는 환자에게도 쓰면 안 돼요. 신중 투여 대상도 있어요. 임신을 계획하는 성인 남성은 생식능에 영향을 줄 수 있어 의사 판단 하에 신중히 써야 하고, 간장애 환자는 이 약이 광범위하게 대사되고 반감기가 약 3~5주로 길어서 주의해 투여해야 해요. 상호작용도 챙겨야 하는데, 강력한 CYP3A4 억제제(예: 리토나비르)를 만성적으로 복용하는 환자가 함께 쓸 때는 주의가 필요해요. 이 약이 사람의 CYP3A4로 대사되기 때문이에요. 전립선암 검진과도 얽혀요. 이 약은 총 혈청 PSA 농도를 투여 6개월 후 약 50%까지 낮춰서, 검사 수치를 해석할 때 복용 사실을 의사에게 알려야 해요. 보관은 원래 용기 그대로가 원칙이에요. 어떤 약을 고르고 언제 멈출지는 본인 상태에 맞춰 의사와 상의해 정하면 돼요."
