        "content": "두리드정의 부작용은 약을 먹는 남성과 약에 손대는 여성에서 완전히 갈려요. 식약처 허가사항(품목번호 201908233, 텔콘알에프제약) 기준 주성분은 두타스테리드 0.5mg이에요. 5α-reductase를 억제해 남성호르몬 경로를 건드리죠. 그래서 복용하는 남성에게는 발기부전, 성욕 감소, 사정 장애, 여성형 유방처럼 성기능에 얽힌 이상반응이 나타나요.\n\n여성에게는 먹는 문제가 아니라 닿는 문제예요. 이 약은 피부로도 흡수돼요. 임신 가능성이 있는 여성이 부서진 정제를 만지면 흡수된 성분이 남자 태아 발달을 위협할 수 있어요. 그래서 여성은 복용이 아니라 취급 자체가 금기로 묶여요.\n\n위험의 방향이 성별로 다른 셈이죠. 남성은 자기 몸의 변화를 살펴야 해요. 같은 집 여성은 손에 닿는 경로를 차단해야 하고요. 같은 한 알인데 누가 드느냐로 챙길 게 달라져요.",
