        content: "피나스테린정의 주성분은 피나스테리드(Finasteride) 5mg이에요. 5α-환원효소 2형을 선택적으로 억제해서, 테스토스테론이 탈모의 직접 원인인 DHT(디하이드로테스토스테론)로 전환되는 걸 막아요. DHT가 65~70% 감소하면 비대해진 전립선이 점차 줄어들어요.\n\nDHT는 전립선 세포를 증식시켜 전립선이 비대해지게 만드는 핵심 물질이에요. 이걸 줄이면 전립선 크기가 줄어들고 소변 흐름이 개선돼요. 오리지널은 프로스카(한국오가논 5mg)이고, 피나스테린정은 (주)바스칸바이오제약에서 만드는 제네릭이에요.\n\n정제 형태로 코팅 처리가 되어 있어요. 임산부가 분쇄된 정제를 피부로 흡수하면 남성 태아 생식기 발달에 이상이 생길 수 있어서, 코팅 상태 그대로 보관하고 복용해야 해요.",
