        title: "피나스테린정 효과가 나타나려면 얼마나 걸리나요?",
        content: "피나스테린정의 주요 적응증은 양성 전립선비대증(BPH)이에요. 전립선이 커져서 소변 줄기가 약해지거나, 야간뇨, 잔뇨감 같은 배뇨 증상을 개선해요. 급성 요폐(갑자기 소변이 안 나오는 상태) 발생 위험과 수술 필요성도 줄여줘요.\n\n전립선 용적은 평균 6개월 복용 후 20% 이상 감소하는 것으로 보고돼요. 증상 개선을 제대로 평가하려면 최소 6개월 이상 꾸준히 복용해야 해요.\n\n5mg을 임의로 4등분해서 탈모 치료에 쓰는 경우가 있는데, 용량 편차가 커서 효과와 안전성이 보장되지 않아요. 탈모 치료 목적이라면 1mg 허가 제품으로 처방받아야 해요. 비뇨기과에서 진단 후 처방받는 전문의약품이에요.",
