        content: "오스테리드정의 허가 적응증은 만 18세 이상 41세 이하 성인 남성의 남성형 탈모증(안드로겐탈모증)이에요. M자 탈모와 정수리 탈모 모두에 효과가 있어요. DHT를 줄여서 위축된 모낭이 다시 굵은 모발을 생산하도록 돕는 방식이에요.\n\n효과를 판단하려면 최소 3개월, 보통 6개월 이상 꾸준히 복용해야 해요. 복용 초기에 오히려 빠지는 것처럼 느껴질 수 있는데, 성장기로 전환되면서 기존 휴지기 모발이 밀려나는 정상 과정이에요.\n\n복용을 중단하면 12개월 이내에 치료 효과가 사라지고 탈모가 다시 진행돼요. 효과를 유지하려면 장기 복용이 필수예요. 원형탈모, 여성형 탈모, 41세 초과 남성, 출산 관련 탈모에는 효과가 없어요. 피부과에서 탈모 진단 후 처방받아야 하는 전문의약품이에요.",
